message.content:
{
  "architecture": {
    "summary": "앱이 내부 SMS 및 외부 메트릭스로 정상 전송하고, 실패 시 외부 지원으로 전송하는 구조",
    "components": [
      {
        "name": "app",
        "role": "사용자 등록 요청 처리",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "dispatcher.py",
        "role": "메시지 분배 로직",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "broker.py",
        "role": "메시지 중계 및 저장",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "r1: INTERNAL SMS",
        "role": "내부 SMS 전송",
        "isolationStatus": "ISOLATED",
        "state": "OBSERVED"
      },
      {
        "name": "r2: EXTERNAL Metrics",
        "role": "외부 메트릭스 전송",
        "isolationStatus": "ISOLATED",
        "state": "OBSERVED"
      },
      {
        "name": "r3: EXTERNAL Support",
        "role": "외부 지원 전송",
        "isolationStatus": "ISOLATED",
        "state": "OBSERVED"
      }
    ]
  },
  "flows": [
    {
      "source": "app",
      "target": "r1: INTERNAL SMS",
      "condition": "정상 전송",
      "data": "사용자 등록 이벤트",
      "boundary": "INTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "app",
      "target": "r2: EXTERNAL Metrics",
      "condition": "정상 전송",
      "data": "사용자 등록 이벤트",
      "boundary": "EXTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "app",
      "target": "r3: EXTERNAL Support",
      "condition": "전송 실패 시",
      "data": "사용자 등록 이벤트",
      "boundary": "EXTERNAL",
      "state": "INFERRED"
    },
    {
      "source": "broker.py",
      "target": "r1: INTERNAL SMS",
      "condition": "메시지 중계",
      "data": "복제된 이벤트",
      "boundary": "INTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "broker.py",
      "target": "r2: EXTERNAL Metrics",
      "condition": "메시지 중계",
      "data": "복제된 이벤트",
      "boundary": "EXTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "broker.py",
      "target": "r3: EXTERNAL Support",
      "condition": "메시지 중계",
      "data": "복제된 이벤트",
      "boundary": "EXTERNAL",
      "state": "INFERRED"
    }
  ],
  "uncertainties": [
    "실패 전송 경로에서 r3으로의 데이터 전달이 코드에 명시되지 않음",
    "broker.py가 MESSAGES 리스트에 이벤트를 저장하는 방식이 외부에 노출될 수 있음",
    "app.py에서 fail 파라미터를 사용할 때 ARCHIVE에 저장되는 동작이 보장되지 않음",
    "deployment.json의 trust boundary 설정이 실제 시스템과 일치하는지 확인 불가"
  ]
}
